#include <iostream>

using namespace std;

int n, m, result;

void in() {
    cin >> n >> m;
}

void out() {
    cout << result << endl;
}

void run() {
    int remain = n;
    int d = 1;
    for (; remain > 0; d++) {
        if (d % m != 0) {
            remain--;
        }
    }
    result = d - 1;
}

int main() {
    in();
    run();
    out();
    return 0;
}

